import React from 'react';
import * as ReactHookForm from "react-hook-form";
const { useForm } = ReactHookForm;

export default function CreateEventForm() {
  const { register, handleSubmit } = useForm();

  const onSubmit = async (data: any) => {
    // Handle form submission logic here
    console.log(data);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
      <div>
        <label htmlFor="title" className="block text-sm font-medium text-gray-700">
          Title
        </label>
        <input
          id="title"
          {...register('title', { required: true })}
          className="input"
          placeholder="Event Title"
        />
      </div>

      <div>
        <label htmlFor="type" className="block text-sm font-medium text-gray-700">
          Type
        </label>
        <select id="type" {...register('type', { required: true })} className="input">
          <option value="Announcement">Announcement</option>
          <option value="Tour">Tour</option>
        </select>
      </div>

      <div>
        <label htmlFor="description" className="block text-sm font-medium text-gray-700">
          Description
        </label>
        <textarea
          id="description"
          {...register('description', { required: true })}
          className="input"
          placeholder="Event Description"
        />
      </div>

      <div>
        <label htmlFor="sequence" className="block text-sm font-medium text-gray-700">
          Sequence (DEP-ARR)
        </label>
        <input
          id="sequence"
          {...register('sequence', { required: true })}
          className="input"
          placeholder="Departure - Arrival"
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700">Date</label>
        <div className="flex space-x-4">
          <input
            type="date"
            {...register('startDate')}
            className="input"
            placeholder="Start Date"
          />
          <input
            type="date"
            {...register('endDate')}
            className="input"
            placeholder="End Date"
          />
        </div>
        <div className="flex items-center space-x-2 mt-2">
          <input
            type="checkbox"
            id="noDate"
            {...register('noDate')}
            className="checkbox"
          />
          <label htmlFor="noDate" className="text-sm text-gray-700">
            No Date
          </label>
        </div>
      </div>

      <div>
        <label htmlFor="map" className="block text-sm font-medium text-gray-700">
          Map
        </label>
        <div className="map-placeholder">Map Component Placeholder</div>
      </div>

      <div>
        <label htmlFor="airframes" className="block text-sm font-medium text-gray-700">
          Airframes Allowed on Tour
        </label>
        <div className="airframes-placeholder">Airframes Selection Placeholder</div>
      </div>

      <button type="submit" className="btn-primary">
        Create Event
      </button>
    </form>
  );
}